sysauto_script.script:
// Generate weekly attendance summary
var startDate = new GlideDateTime();
startDate.addDaysLocalTime(-7);

var attendanceGR = new GlideRecord('x_1843073_institut_attendance');
attendanceGR.addQuery('date', '>=', startDate.getDisplayValue());
attendanceGR.query();

var totalClasses = 0;
var presentCount = 0;

while (attendanceGR.next()) {
    totalClasses++;
    if (attendanceGR.getValue('status') == 'present') {
        presentCount++;
    }
}

var attendanceRate = totalClasses > 0 ? ((presentCount / totalClasses) * 100).toFixed(2) : 0;

// Create weekly summary notification
var weeklyNotif = new GlideRecord('x_1843073_institut_notification');
weeklyNotif.initialize();
weeklyNotif.setValue('title', 'Weekly Attendance Summary');
weeklyNotif.setValue('message', 'This week attendance rate: ' + attendanceRate + '%. Total classes: ' + totalClasses + ', Present: ' + presentCount);
weeklyNotif.setValue('notification_type', 'general');
weeklyNotif.setValue('priority', 'medium');
weeklyNotif.setValue('target_audience', 'all');
weeklyNotif.setValue('active', true);
weeklyNotif.insert();

gs.info('Weekly report generated - Attendance Rate: ' + attendanceRate + '%');
